class Setup:Form {
 static void Preview(Form form,string path){StudioStyle.Polish(form);var items=new System.Collections.Generic.List<Control>();foreach(Control control in form.Controls)items.Add(control);using(var root=new Panel{Size=form.ClientSize,BackColor=form.BackColor,Font=form.Font}){foreach(var control in items)control.Parent=null;root.Controls.AddRange(items.ToArray());root.CreateControl();root.PerformLayout();using(var image=new Bitmap(root.Width,root.Height)){root.DrawToBitmap(image,new Rectangle(0,0,image.Width,image.Height));image.Save(path);}}}
 static string InstallDir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","JingFamily");
 static string MenuDir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.StartMenu),"Programs","景·谱");
 static string DesktopLink=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"景·谱.lnk");
 const string RegistryPath="Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\JingFamily";
 static bool Notice(string message,bool question){using(var f=new Form{Text=question?"请确认 · 景·谱":"景·谱",ClientSize=new Size(640,340),StartPosition=FormStartPosition.CenterParent,Font=new Font("Microsoft YaHei UI",10),BackColor=StudioStyle.Canvas,ShowInTaskbar=false}){using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("JingPuIcon"))using(var icon=new Icon(stream))f.Icon=(Icon)icon.Clone();var top=new Panel{Dock=DockStyle.Top,Height=76,BackColor=Color.White};using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("JingPuLogo"))using(var image=Image.FromStream(stream))top.Controls.Add(new PictureBox{Image=new Bitmap(image),SizeMode=PictureBoxSizeMode.Zoom,Location=new Point(22,16),Size=new Size(44,44)});top.Controls.Add(new Label{Text="景·谱",AutoSize=true,Font=new Font(f.Font.FontFamily,16,FontStyle.Bold),ForeColor=Color.FromArgb(29,75,61),Location=new Point(82,23)});f.Controls.Add(top);var footer=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=72,BackColor=Color.White,FlowDirection=FlowDirection.RightToLeft,Padding=new Padding(18,10,10,0)};var ok=new StudioButton{Text=question?"确认":"确定",Width=100,Height=38,DialogResult=question?DialogResult.Yes:DialogResult.OK};footer.Controls.Add(ok);f.AcceptButton=ok;if(question){var cancel=new StudioButton{Text="取消",Width=100,Height=38,DialogResult=DialogResult.No};footer.Controls.Add(cancel);f.CancelButton=cancel;}f.Controls.Add(footer);var body=new Panel{Dock=DockStyle.Fill,Padding=new Padding(22,0,22,12)};body.Controls.Add(new TextBox{Text=message,Multiline=true,ReadOnly=true,BorderStyle=BorderStyle.None,ScrollBars=ScrollBars.Vertical,BackColor=f.BackColor,Dock=DockStyle.Fill});f.Controls.Add(body);body.BringToFront();var owner=Form.ActiveForm;return (owner==null?f.ShowDialog():f.ShowDialog(owner))==DialogResult.Yes;}}
 static void RemoveLegacyShortcut(string path,string expected){if(!File.Exists(path))return;object shell=null,link=null;try{Type type=Type.GetTypeFromProgID("WScript.Shell");shell=Activator.CreateInstance(type);link=type.InvokeMember("CreateShortcut",BindingFlags.InvokeMethod,null,shell,new object[]{path});string target=(string)link.GetType().InvokeMember("TargetPath",BindingFlags.GetProperty,null,link,null);if(String.Equals(Path.GetFullPath(target),Path.GetFullPath(expected),StringComparison.OrdinalIgnoreCase))File.Delete(path);}catch{}finally{if(link!=null)Marshal.FinalReleaseComObject(link);if(shell!=null)Marshal.FinalReleaseComObject(shell);}}
 static void LegacyCleanup(){string oldMenu=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.StartMenu),"Programs","景氏家谱");RemoveLegacyShortcut(Path.Combine(oldMenu,"景氏家谱.lnk"),Path.Combine(InstallDir,"JingFamily.exe"));RemoveLegacyShortcut(Path.Combine(oldMenu,"卸载景氏家谱.lnk"),Path.Combine(InstallDir,"Uninstall.exe"));RemoveLegacyShortcut(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"景氏家谱.lnk"),Path.Combine(InstallDir,"JingFamily.exe"));if(Directory.Exists(oldMenu)&&Directory.GetFileSystemEntries(oldMenu).Length==0)Directory.Delete(oldMenu);}
 CheckBox desktop,launch;Button install;Label state;bool remove;
 public Setup(bool uninstall){remove=uninstall;using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("JingPuIcon"))using(var ico=new Icon(stream))Icon=(Icon)ico.Clone();Text=uninstall?"卸载景·谱":"安装景·谱 1.5";ClientSize=new Size(640,430);StartPosition=FormStartPosition.CenterScreen;FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;Font=new Font("Microsoft YaHei UI",10);BackColor=StudioStyle.Canvas;var banner=new Panel{Dock=DockStyle.Top,Height=108,BackColor=Color.White};banner.Controls.Add(new Label{Text=uninstall?"卸载景·谱":"景·谱",Font=new Font(Font.FontFamily,25,FontStyle.Bold),ForeColor=StudioStyle.Green,AutoSize=true,Location=new Point(108,20)});banner.Controls.Add(new Label{Text="记录亲缘 · 传承家风 · 珍藏故事",ForeColor=StudioStyle.Muted,AutoSize=true,Location=new Point(111,75)});using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("JingPuLogo"))using(var img=Image.FromStream(stream))banner.Controls.Add(new PictureBox{Image=new Bitmap(img),SizeMode=PictureBoxSizeMode.Zoom,Location=new Point(28,23),Size=new Size(60,60)});Controls.Add(banner);
  state=new Label{Text=uninstall?"将移除程序、快捷方式与安装信息。\n家谱档案与附件将保留在本机，不会删除。":"欢迎安装景·谱。无需联网，无需管理员权限。\n\n安装位置：\n"+InstallDir,Location=new Point(30,132),Size=new Size(580,108)};Controls.Add(state);
  desktop=new CheckBox{Text="创建桌面快捷方式",Checked=true,AutoSize=true,Location=new Point(32,253),Visible=!uninstall};launch=new CheckBox{Text="安装完成后启动景·谱",Checked=true,AutoSize=true,Location=new Point(32,286),Visible=!uninstall};Controls.Add(desktop);Controls.Add(launch);
  install=new StudioButton{Text=uninstall?"卸载程序":"立即安装",BackColor=Color.FromArgb(29,75,61),ForeColor=Color.White,FlatStyle=FlatStyle.Flat,Location=new Point(460,350),Size=new Size(145,45)};install.Click+=(s,e)=>{try{if(remove)BeginRemove();else Install();}catch(Exception ex){install.Enabled=true;Notice(ex.GetBaseException().Message,false);}};Controls.Add(install);Controls.Add(new Label{Text="微信公众号：景同志  /  小红书：景同学",Location=new Point(30,363),AutoSize=true,ForeColor=Color.Gray,Font=new Font(Font.FontFamily,9)});
 }
 static void Extract(string dir){Directory.CreateDirectory(dir);using(var source=Assembly.GetExecutingAssembly().GetManifestResourceStream("JingFamily.exe")){if(source==null)throw new Exception("安装包资源缺失。");string tmp=Path.Combine(dir,"JingFamily.exe.new");using(var target=File.Create(tmp))source.CopyTo(target);string dest=Path.Combine(dir,"JingFamily.exe");if(File.Exists(dest))File.Replace(tmp,dest,null);else File.Move(tmp,dest);}}
 static void Shortcut(string path,string target,string args){object shell=null,link=null;try{Type type=Type.GetTypeFromProgID("WScript.Shell");shell=Activator.CreateInstance(type);link=type.InvokeMember("CreateShortcut",BindingFlags.InvokeMethod,null,shell,new object[]{path});var lt=link.GetType();lt.InvokeMember("TargetPath",BindingFlags.SetProperty,null,link,new object[]{target});lt.InvokeMember("Arguments",BindingFlags.SetProperty,null,link,new object[]{args});lt.InvokeMember("WorkingDirectory",BindingFlags.SetProperty,null,link,new object[]{InstallDir});lt.InvokeMember("Description",BindingFlags.SetProperty,null,link,new object[]{"景·谱 · 离线家谱工具"});lt.InvokeMember("Save",BindingFlags.InvokeMethod,null,link,null);}finally{if(link!=null)Marshal.FinalReleaseComObject(link);if(shell!=null)Marshal.FinalReleaseComObject(shell);}}
 void Install(){install.Enabled=false;state.Text="正在安装，请稍候…";state.Refresh();Extract(InstallDir);string uninstall=Path.Combine(InstallDir,"Uninstall.exe");if(!String.Equals(Application.ExecutablePath,uninstall,StringComparison.OrdinalIgnoreCase))File.Copy(Application.ExecutablePath,uninstall,true);Directory.CreateDirectory(MenuDir);Shortcut(Path.Combine(MenuDir,"景·谱.lnk"),Path.Combine(InstallDir,"JingFamily.exe"),"");Shortcut(Path.Combine(MenuDir,"卸载景·谱.lnk"),uninstall,"--uninstall");if(desktop.Checked)Shortcut(DesktopLink,Path.Combine(InstallDir,"JingFamily.exe"),"");using(var key=Registry.CurrentUser.CreateSubKey(RegistryPath)){key.SetValue("DisplayName","景·谱");key.SetValue("DisplayVersion","1.5.0");key.SetValue("Publisher","景同志 / 景同学");key.SetValue("InstallLocation",InstallDir);key.SetValue("DisplayIcon",Path.Combine(InstallDir,"JingFamily.exe"));key.SetValue("UninstallString","\""+uninstall+"\" --uninstall");key.SetValue("NoModify",1,RegistryValueKind.DWord);key.SetValue("NoRepair",1,RegistryValueKind.DWord);}LegacyCleanup();state.Text="安装完成。\n\n可从桌面或开始菜单打开景·谱。\n家谱数据单独保存，升级时会保留。";install.Text="完成";install.Enabled=true;bool start=launch.Checked;launch.Enabled=false;desktop.Enabled=false;install.Click-=(s,e)=>{};install.Visible=false;var done=new StudioButton{Text="完成",Location=new Point(460,350),Size=new Size(145,45)};done.Click+=(s,e)=>{if(start)Process.Start(Path.Combine(InstallDir,"JingFamily.exe"));Close();};Controls.Add(done);}
 void BeginRemove(){if(!Notice("确定卸载景·谱？所有家谱及回收区数据将保留。",true))return;string temp=Path.Combine(Path.GetTempPath(),"JingFamily-Uninstall-"+Guid.NewGuid().ToString("N")+".exe");File.Copy(Application.ExecutablePath,temp);Process.Start(temp,"--remove "+Process.GetCurrentProcess().Id);Close();}
 static void Remove(int pid){try{try{Process.GetProcessById(pid).WaitForExit(15000);}catch(ArgumentException){}foreach(string file in new[]{"JingFamily.exe","JingFamily.exe.new","Uninstall.exe"}){string path=Path.Combine(InstallDir,file);if(File.Exists(path))File.Delete(path);}foreach(string path in new[]{Path.Combine(MenuDir,"景·谱.lnk"),Path.Combine(MenuDir,"卸载景·谱.lnk"),DesktopLink})if(File.Exists(path))File.Delete(path);if(Directory.Exists(MenuDir)&&Directory.GetFileSystemEntries(MenuDir).Length==0)Directory.Delete(MenuDir);if(Directory.Exists(InstallDir)&&Directory.GetFileSystemEntries(InstallDir).Length==0)Directory.Delete(InstallDir);LegacyCleanup();Registry.CurrentUser.DeleteSubKeyTree(RegistryPath,false);Notice("卸载完成，家谱数据已保留。\n"+Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"JingFamily"),false);}catch(Exception e){Notice("卸载未完成，请关闭景·谱后重试。\n"+e.Message,false);}}
 [STAThread] static int Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);if(args.Length==2&&args[0]=="--extract-test"){Extract(args[1]);Shortcut(Path.Combine(args[1],"test-shortcut.lnk"),Path.Combine(Path.GetFullPath(args[1]),"JingFamily.exe"),"");using(var form=new Setup(false)){form.CreateControl();Preview(form,Path.Combine(args[1],"安装界面预览.png"));}using(var form=new Setup(true)){form.CreateControl();Preview(form,Path.Combine(args[1],"卸载界面预览.png"));}File.WriteAllText(Path.Combine(args[1],"installer-check.txt"),"PASS: payload extraction, COM shortcut, install/uninstall UI construction");return 0;}if(args.Length==2&&args[0]=="--remove"){int pid;if(!Int32.TryParse(args[1],out pid))return 1;Remove(pid);return 0;}Application.Run(new Setup(args.Length>0&&args[0]=="--uninstall"));return 0;}
}
